import React, { useEffect, useRef, cloneElement, ReactElement, Children } from 'react';
import { X } from 'lucide-react';
import { Button } from '@heroui/react';

interface DrawerProps {
  isOpen: boolean;
  onClose: () => void;
  children: React.ReactNode;
  position?: 'left' | 'right';
  ariaLabel?: string;
}

export const Drawer: React.FC<DrawerProps> = ({
  isOpen,
  onClose,
  children,
  position = 'left',
  ariaLabel = 'Drawer'
}) => {
  const drawerRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLElement | null>(null);

  // Store the trigger element when drawer opens
  useEffect(() => {
    if (isOpen && !triggerRef.current) {
      triggerRef.current = document.activeElement as HTMLElement;
    }
  }, [isOpen]);

  // Focus management
  useEffect(() => {
    if (isOpen) {
      // Focus on first interactive element
      const timeoutId = setTimeout(() => {
        const firstFocusable = drawerRef.current?.querySelector(
          'button, a, input, textarea, [tabindex]:not([tabindex="-1"])'
        ) as HTMLElement;
        firstFocusable?.focus();
      }, 100);

      // Disable body scroll
      document.body.style.overflow = 'hidden';

      return () => clearTimeout(timeoutId);
    } else {
      // Restore body scroll
      document.body.style.overflow = '';

      // Return focus to trigger
      if (triggerRef.current) {
        triggerRef.current.focus();
        triggerRef.current = null;
      }
    }
  }, [isOpen]);

  // ESC key handler
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        onClose();
      }
    };

    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [isOpen, onClose]);

  // Focus trap
  useEffect(() => {
    if (!isOpen) return;

    const handleTab = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return;

      const focusableElements = drawerRef.current?.querySelectorAll(
        'button, a, input, textarea, [tabindex]:not([tabindex="-1"])'
      ) as NodeListOf<HTMLElement>;

      if (!focusableElements || focusableElements.length === 0) return;

      const firstElement = focusableElements[0];
      const lastElement = focusableElements[focusableElements.length - 1];

      if (e.shiftKey) {
        if (document.activeElement === firstElement) {
          e.preventDefault();
          lastElement.focus();
        }
      } else {
        if (document.activeElement === lastElement) {
          e.preventDefault();
          firstElement.focus();
        }
      }
    };

    window.addEventListener('keydown', handleTab);
    return () => window.removeEventListener('keydown', handleTab);
  }, [isOpen]);

  if (!isOpen) return null;

  const positionClasses = position === 'left'
    ? 'left-0 translate-x-0'
    : 'right-0 translate-x-0';

  return (
    <>
      {/* Overlay */}
      <div
        role="presentation"
        aria-hidden="true"
        className={`
          fixed inset-0 z-[60]
          bg-black/20 backdrop-blur-sm
          transition-opacity duration-300
          ${isOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}
        `}
        onClick={onClose}
      />

      {/* Drawer */}
      <div
        ref={drawerRef}
        role="dialog"
        aria-modal="true"
        aria-label={ariaLabel}
        className={`
          fixed top-0 bottom-0 z-[70]
          w-[80%] max-w-[320px]
          md:w-[60%] md:max-w-[400px]
          lg:w-[400px] lg:max-w-[400px]
          ${positionClasses}
          bg-white dark:bg-slate-900
          shadow-2xl
          border-r border-neutral-200 dark:border-neutral-700
          transition-transform duration-500 ease-[cubic-bezier(0.32,0.72,0,1)]
          ${isOpen ? 'translate-x-0' : position === 'left' ? '-translate-x-full' : 'translate-x-full'}
          flex flex-col
        `}
      >
        {/* Close Button */}
        <div className="flex justify-end p-4 border-b border-neutral-100 dark:border-neutral-800">
          <Button
            isIconOnly
            size="sm"
            variant="light"
            onPress={onClose}
            aria-label="关闭"
          >
            <X className="w-5 h-5" />
          </Button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto">
          {children}
        </div>
      </div>
    </>
  );
};
